package org.greenrobot.eventbus;

/**
 * Standalone test to verify that EventBusBuilder.skipMethodVerificationFor() actually works.
 *
 * Bug: The field skipMethodVerificationForClasses is populated by the public API
 * skipMethodVerificationFor(Class<?>) but is NEVER read or used anywhere.
 * SubscriberMethodFinder has no reference to it. This means the public API has no effect.
 */
public class SkipMethodVerificationBugTest {

    /**
     * A subscriber with an illegal @Subscribe method (static).
     * With strictMethodVerification=true, registering this should throw EventBusException.
     * With skipMethodVerificationFor(StaticSubscriber.class), it should NOT throw.
     */
    public static class StaticSubscriber {
        @Subscribe
        public static void onEvent(Object event) {
        }
    }

    /**
     * A subscriber with an illegal @Subscribe method (wrong param count).
     * With strictMethodVerification=true, registering this should throw EventBusException.
     * With skipMethodVerificationFor(NoArgSubscriber.class), it should NOT throw.
     */
    public static class NoArgSubscriber {
        @Subscribe
        public void onEvent() {
        }
    }

    public static void main(String[] args) {
        int failed = 0;

        // Test 1: Without skip, strict mode should throw for static method
        System.out.println("Test 1: strict mode without skip should throw for static @Subscribe method");
        try {
            EventBus.clearCaches();
            EventBus bus = EventBus.builder().strictMethodVerification(true).build();
            bus.register(new StaticSubscriber());
            System.out.println("  FAIL: Expected EventBusException but got none");
            failed++;
        } catch (EventBusException e) {
            System.out.println("  PASS: Got expected exception: " + e.getMessage());
        }

        // Test 2: With skip, static method should be tolerated (THIS IS THE BUG - it still throws)
        System.out.println("Test 2: strict mode WITH skip should tolerate static @Subscribe method");
        try {
            EventBus.clearCaches();
            EventBus bus = EventBus.builder()
                    .strictMethodVerification(true)
                    .skipMethodVerificationFor(StaticSubscriber.class)
                    .build();
            bus.register(new StaticSubscriber());
            System.out.println("  PASS: Registration succeeded (skipMethodVerificationFor works)");
        } catch (EventBusException e) {
            System.out.println("  FAIL: Bug confirmed! skipMethodVerificationFor has NO effect");
            System.out.println("  Exception: " + e.getMessage());
            failed++;
        }

        // Test 3: With skip, wrong param count should be tolerated (THIS IS THE BUG - it still throws)
        System.out.println("Test 3: strict mode WITH skip should tolerate wrong param count @Subscribe method");
        try {
            EventBus.clearCaches();
            EventBus bus = EventBus.builder()
                    .strictMethodVerification(true)
                    .skipMethodVerificationFor(NoArgSubscriber.class)
                    .build();
            bus.register(new NoArgSubscriber());
            System.out.println("  PASS: Registration succeeded (skipMethodVerificationFor works)");
        } catch (EventBusException e) {
            System.out.println("  FAIL: Bug confirmed! skipMethodVerificationFor has NO effect");
            System.out.println("  Exception: " + e.getMessage());
            failed++;
        }

        System.out.println();
        if (failed > 0) {
            System.out.println("RESULT: " + failed + " test(s) FAILED - skipMethodVerificationFor is a dead API");
            System.exit(1);
        } else {
            System.out.println("RESULT: All tests PASSED - skipMethodVerificationFor works correctly");
            System.exit(0);
        }
    }
}

